const s = $input.first().json.snapshot || {};
const p = s.project || {};
const b = s.briefing || {};
const d = s.design || {};
const ce = s.cost_estimate || {};
const invSum = s.invoices_summary || {};
const aftercare = s.aftercare || [];
const paths = s.pathology || [];
const permits = s.permits || [];
const certs = s.certifications || [];
const inv = s.invoices || [];
const fmt = n => Number(n || 0).toLocaleString('es-ES');
const sevColor = { urgent: '#dc2626', critical: '#7f1d1d', high: '#ea580c', medium: '#f59e0b', low: '#10b981' };
const pct = ce.total_estimated && invSum.total ? Math.round((invSum.total / ce.total_estimated) * 100) : 0;

const section = (title, body, count) => '<section style="margin:24px 0;padding:16px;background:#f9fafb;border-radius:8px"><h2 style="margin:0 0 12px;color:#1f2937;font-size:18px">' + title + (count !== undefined ? ' <span style="color:#6b7280;font-size:14px;font-weight:normal">(' + count + ')</span>' : '') + '</h2>' + body + '</section>';

const briefingHtml = b.summary
  ? '<p><b>Resumen:</b> ' + b.summary + '</p>' +
    '<p><b>Objetivos:</b><br>' + (Array.isArray(b.objectives) ? b.objectives.map(o => typeof o === 'string' ? o : JSON.stringify(o)).join('<br>') : '—') + '</p>' +
    '<p><b>Espacios afectados:</b> ' + (Array.isArray(b.rooms_affected) ? b.rooms_affected.length + ' espacios' : '—') + '</p>'
  : '<p style="color:#6b7280">Sin briefing aprobado todavía.</p>';

const designHtml = d.title
  ? '<p><b>Opción ' + (d.option_number || '?') + ':</b> ' + d.title + '</p><p style="color:#374151">' + (d.description || '').substring(0, 400) + '...</p>'
  : '<p style="color:#6b7280">Sin opción de diseño seleccionada.</p>';

const financialHtml = ce.total_estimated
  ? '<table style="width:100%;border-collapse:collapse">' +
    '<tr><td style="padding:6px 0"><b>Estimado</b></td><td style="padding:6px 0;text-align:right">' + fmt(ce.total_estimated) + ' EUR</td></tr>' +
    '<tr><td style="padding:6px 0"><b>Facturado</b></td><td style="padding:6px 0;text-align:right">' + fmt(invSum.total) + ' EUR (' + pct + '%)</td></tr>' +
    '<tr><td style="padding:6px 0"><b>Facturas pendientes revisión</b></td><td style="padding:6px 0;text-align:right">' + (invSum.pending || 0) + '</td></tr>' +
    '<tr><td style="padding:6px 0"><b>Certificaciones emitidas</b></td><td style="padding:6px 0;text-align:right">' + certs.length + '</td></tr>' +
    '</table>' +
    (certs.length > 0 ? '<p style="margin-top:12px"><b>Certificaciones:</b><br>' + certs.map(c => 'v' + c.version + ': ' + c.percentage + '% → ' + fmt(c.amount) + ' EUR (' + c.status + ')').join('<br>') + '</p>' : '')
  : '<p style="color:#6b7280">Sin estimación de coste todavía.</p>';

const pathologyHtml = paths.length > 0
  ? paths.map(p => '<li><span style="background:' + (sevColor[p.severity] || '#6b7280') + ';color:white;padding:1px 6px;border-radius:3px;font-size:11px">' + (p.severity || '?').toUpperCase() + '</span> ' + (p.type || '?') + ' — ' + (p.description || '').substring(0, 150) + '</li>').join('')
  : '<li style="color:#6b7280">Sin patologías detectadas.</li>';

const aftercareHtml = aftercare.length > 0
  ? aftercare.slice(0, 10).map(a => '<li><span style="background:' + (sevColor[a.severity] || '#6b7280') + ';color:white;padding:1px 6px;border-radius:3px;font-size:11px">' + (a.severity || '?').toUpperCase() + '</span> ' + (a.category || '?') + ' — ' + (a.status || '?') + ' — ' + (a.description || '').substring(0, 120) + (a.assigned_to ? ' → ' + a.assigned_to : '') + '</li>').join('')
  : '<li style="color:#6b7280">Sin incidencias post-entrega.</li>';

const permitsHtml = permits.length > 0
  ? permits.map(pe => '<li><b>' + (pe.application_type || '?') + '</b> en ' + (pe.entity || '?') + ' — status <code>' + (pe.status || '?') + '</code>' + (pe.expediente_id ? ' (exp. ' + pe.expediente_id + ')' : '') + '</li>').join('')
  : '<li style="color:#6b7280">Sin trámites administrativos registrados.</li>';

const html = '<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>' + (p.name || 'Proyecto') + ' — resumen</title>' +
'<style>body{font-family:-apple-system,Arial,sans-serif;max-width:780px;margin:24px auto;padding:16px;color:#1f2937;background:white}h1{color:#0f172a;font-size:26px;margin:0}.meta{color:#64748b;font-size:14px;margin-top:4px}ul{padding-left:20px;line-height:1.7}li{margin-bottom:6px}.phase{display:inline-block;background:#1e3a8a;color:white;padding:4px 10px;border-radius:4px;font-size:13px;margin-top:8px}</style>' +
'</head><body>' +
'<h1>' + (p.name || 'Proyecto sin nombre') + '</h1>' +
'<div class="meta">' + (p.project_type || '—') + ' • ' + (p.property_type || '—') + ' ' + (p.property_area_m2 ? p.property_area_m2 + 'm²' : '') + ' • ' + (p.location || '—') + '</div>' +
'<span class="phase">Fase actual: ' + (p.current_phase || '?') + '</span>' +
(p.handover_date ? '<div class="meta">Entregado: ' + p.handover_date + '</div>' : '') +
section('Briefing', briefingHtml) +
section('Diseño seleccionado', designHtml) +
section('Resumen financiero', financialHtml) +
section('Patologías detectadas', '<ul>' + pathologyHtml + '</ul>', paths.length) +
section('Trámites administrativos', '<ul>' + permitsHtml + '</ul>', permits.length) +
section('Postventa LOE', '<ul>' + aftercareHtml + '</ul>', aftercare.length) +
'<p style="text-align:center;color:#94a3b8;font-size:12px;margin-top:32px">Generado por ArquitAI — ' + new Date().toLocaleString('es-ES') + '</p>' +
'</body></html>';
return [{ json: { html: html } }];
